'use strict';
const assert = require('node:assert/strict');
const escapeStringRegexp = require('./index.js');
const kind = process.argv[2];
if (kind === 'unicode') {
  for (const value of ['-', 'foo - bar', 'a-b']) {
    assert(new RegExp('^' + escapeStringRegexp(value) + '$', 'u').test(value));
  }
  assert(new RegExp('[' + escapeStringRegexp('-') + ']', 'u').test('-'));
  console.log('PASS Unicode literal and character-class hyphens');
} else if (kind === 'literal') {
  const value = '\\ ^ $ * + ? . ( ) | { } [ ]';
  const regex = new RegExp('^' + escapeStringRegexp(value) + '$', 'u');
  assert(regex.test(value));
  assert(!regex.test('different input'));
  console.log('PASS existing metacharacter escaping');
} else if (kind === 'types') {
  assert.throws(() => escapeStringRegexp(null), TypeError);
  assert.throws(() => escapeStringRegexp(42), TypeError);
  assert.equal(escapeStringRegexp(''), '');
  console.log('PASS type rejection and empty input');
} else {
  throw new Error('Unknown owner-configured check');
}

